    for i in range(quantity):
        if random_products:
            product = random.choice(products)
        else:
            product = products[i]
        quantity = random.randint(1, 5)
        price_info = product.get_price_info(pricing_context, quantity=quantity)
        shop_product = product.get_shop_instance(source.shop)
