    def _open(self):
        fp = PSFile(self.fp)
        s = fp.read(512)
        if s[:4] == "%!PS":
            offset = 0
            fp.seek(0, 2)
            length = fp.tell()
        elif i32(s) == 0xC6D3D0C5:
            offset = i32(s[4:])
            length = i32(s[8:])
            fp.seek(offset)
        else:
            raise SyntaxError("not an EPS file")
        fp.seek(offset)
        box = None
        self.mode = "RGB"
        self.size = 1, 1
        s = fp.readline()
        while s:
            if len(s) > 255:
                raise SyntaxError("not an EPS file")
            if s[-2:] == '\r\n':
                s = s[:-2]
            elif s[-1:] == '\n':
                s = s[:-1]
            try:
                m = split.match(s)
            except re.error as v:
                raise SyntaxError("not an EPS file")
            if m:
                k, v = m.group(1, 2)
                self.info[k] = v
                if k == "BoundingBox":
                    try:
                        box = [int(float(s)) for s in v.split()]
                        self.size = box[2] - box[0], box[3] - box[1]
                        self.tile = [("eps", (0,0) + self.size, offset,
                                      (length, box))]
                    except:
                        pass
            else:
                m = field.match(s)
                if m:
                    k = m.group(1)
                    if k == "EndComments":
                        break
                    if k[:8] == "PS-Adobe":
                        self.info[k[:8]] = k[9:]
                    else:
                        self.info[k] = ""
                elif s[0:1] == '%':
                    pass
                else:
                    raise IOError("bad EPS header")
            s = fp.readline()
            if s[:1] != "%":
                break
        while s[0] == "%":
            if len(s) > 255:
                raise SyntaxError("not an EPS file")
            if s[-2:] == '\r\n':
                s = s[:-2]
            elif s[-1:] == '\n':
                s = s[:-1]
            if s[:11] == "%ImageData:":
                [x, y, bi, mo, z3, z4, en, id] =\
                    s[11:].split(None, 7)
                x = int(x); y = int(y)
                bi = int(bi)
                mo = int(mo)
                en = int(en)
                if en == 1:
                    decoder = "eps_binary"
                elif en == 2:
                    decoder = "eps_hex"
                else:
                    break
                if bi != 8:
                    break
                if mo == 1:
                    self.mode = "L"
                elif mo == 2:
                    self.mode = "LAB"
                elif mo == 3:
                    self.mode = "RGB"
                else:
                    break
                if id[:1] == id[-1:] == '"':
                    id = id[1:-1]
                while True:
                    s = fp.readline()
                    if not s:
                        break
                    if s[:len(id)] == id:
                        self.size = x, y
                        self.tile2 = [(decoder,
                                       (0, 0, x, y),
                                       fp.tell(),
                                       0)]
                        return
            s = fp.readline()
            if not s:
                break
        if not box:
            raise IOError("cannot determine EPS bounding box")
    def load(self, scale=1):
        if not self.tile:
            return
        self.im = Ghostscript(self.tile, self.size, self.fp, scale)
        self.mode = self.im.mode
        self.size = self.im.size
