    plugin = api.get_plugin_config()
    conf_menu = []
    plugin_menu = []
    for entry in sorted(conf.keys()):
        conf_menu.append((entry, conf[entry].description))
    for entry in sorted(plugin.keys()):
        plugin_menu.append((entry, plugin[entry].description))
