class Transfers:
    def _file_request_download(self, msg, i):
        log.add_transfer("Received file upload request %(request)s for file %(filename)s from user %(user)s", {
            "request": msg.req,
            "filename": i.filename,
            "user": i.user
        })
        incompletedir = self.config.sections["transfers"]["incompletedir"]
        needupdate = True
        if i.conn is None and i.size is not None:
            i.conn = msg.conn
            i.req = None
            if i in self.transfer_request_times:
                del self.transfer_request_times[i]
            if not incompletedir:
                if i.path:
                    incompletedir = i.path
                else:
                    incompletedir = self.get_default_download_folder(i.user)
            try:
                if not os.access(incompletedir, os.F_OK):
                    os.makedirs(incompletedir)
                if not os.access(incompletedir, os.R_OK | os.W_OK | os.X_OK):
                    raise OSError("Download directory %s Permissions error.\nDir Permissions: %s" %
                                  (incompletedir, oct(os.stat(incompletedir)[stat.ST_MODE] & 0o777)))
            except OSError as error:
                log.add(_("OS error: %s"), error)
                self.download_folder_error(i, error)
            else:
                file_handle = None
                try:
                    from hashlib import md5
                    md5sum = md5()
                    md5sum.update((i.filename + i.user).encode('utf-8'))
                    base_name = clean_file(i.filename.replace('/', '\\').split('\\')[-1])
                    incomplete_name = os.path.join(incompletedir, "INCOMPLETE" + md5sum.hexdigest() + base_name)
                    file_handle = open(incomplete_name, 'ab+')
                    if self.config.sections["transfers"]["lock"]:
                        try:
                            import fcntl
                            try:
                                fcntl.lockf(file_handle, fcntl.LOCK_EX | fcntl.LOCK_NB)
                            except IOError as error:
                                log.add(_("Can't get an exclusive lock on file - I/O error: %s"), error)
                        except ImportError:
                            pass
                    file_handle.seek(0, 2)
                    offset = file_handle.tell()
                except IOError as error:
                    log.add(_("Download I/O error: %s"), error)
                    self.abort_transfer(i)
                    i.status = "Local file error"
                else:
                    i.file = file_handle
                    i.lastbytes = offset
                    i.place = 0
                    self.core.statistics.append_stat_value("started_downloads", 1)
                    self.core.pluginhandler.download_started_notification(i.user, i.filename, incomplete_name)
                    if i.size > offset:
                        i.status = "Transferring"
                        i.legacy_attempt = False
                        self.queue.append(slskmessages.DownloadFile(i.conn, file_handle))
                        self.queue.append(slskmessages.FileOffset(i.conn, i.size, offset))
                        log.add_download(
                            _("Download started: user %(user)s, file %(file)s"), {
                                "user": i.user,
                                "file": "%s" % file_handle.name
                            }
                        )
                    else:
                        self.download_finished(file_handle, i)
                        needupdate = False
            if self.downloadsview:
                self.downloadsview.new_transfer_notification()
                if needupdate:
                    self.downloadsview.update(i)
        else:
            log.add_transfer("Download error formally known as 'Unknown file request': %(req)s (%(user)s: %(file)s)", {
                'req': str(vars(msg)),
                'user': i.user,
                'file': i.filename
            })
            self.queue.append(slskmessages.ConnClose(msg.conn))
def open_file_path(file_path, command=None):
    """ Currently used to either open a folder or play an audio file
    Tries to run a user-specified command first, and falls back to
    the system default. """
    try:
        file_path = os.path.normpath(file_path)
        if command and "$" in command:
            execute_command(command, file_path)
        elif sys.platform == "win32":
            os.startfile(file_path)
        elif sys.platform == "darwin":
            execute_command("open $", file_path)
        elif not webbrowser.open(file_path):
            raise webbrowser.Error("no known URL provider available")
    except Exception as error:
        log.add(_("Failed to open file path: %s"), error)
def execute_command(command, replacement=None, background=True, returnoutput=False, placeholder='$'):
    """Executes a string with commands, with partial support for bash-style quoting and pipes.
    The different parts of the command should be separated by spaces, a double
    quotation mark can be used to embed spaces in an argument.
    Pipes can be created using the bar symbol (|).
    If background is false the function will wait for all the launched
    processes to end before returning.
    If the 'replacement' argument is given, every occurance of 'placeholder'
    will be replaced by 'replacement'.
    If the command ends with the ampersand symbol background
    will be set to True. This should only be done by the request of the user,
    if you want background to be true set the function argument.
    The only expected error to be thrown is the RuntimeError in case something
    goes wrong while executing the command.
    Example commands:
    * "C:\\Program Files\\WinAmp\\WinAmp.exe" --xforce "--title=My Window Title"
    * mplayer $
    * echo $ | flite -t """
    from subprocess import PIPE
    from subprocess import Popen
    if returnoutput:
        background = False
    command = command.strip()
    if command.endswith("&"):
        command = command[:-1]
        if returnoutput:
            log.add("Yikes, I was asked to return output but I'm also asked to launch "
                    "the process in the background. returnoutput gets precedent.")
        else:
            background = True
    unparsed = command
    arguments = []
    while unparsed.count('"') > 1:
        (pre, argument, post) = unparsed.split('"', 2)
        if pre:
            arguments += pre.rstrip(' ').split(' ')
        arguments.append(argument)
        unparsed = post.lstrip(' ')
    if unparsed:
        arguments += unparsed.split(' ')
    subcommands = []
    current = []
    for argument in arguments:
        if argument in ('|',):
            subcommands.append(current)
            current = []
        else:
            current.append(argument)
    subcommands.append(current)
    if replacement:
        for i, _ in enumerate(subcommands):
            subcommands[i] = [x.replace(placeholder, replacement) for x in subcommands[i]]
    finalstdout = None
    if returnoutput:
        finalstdout = PIPE
    procs = []
    try:
        if len(subcommands) == 1:
            procs.append(Popen(subcommands[0], stdout=finalstdout))
        else:
            procs.append(Popen(subcommands[0], stdout=PIPE))
            for subcommand in subcommands[1:-1]:
                procs.append(Popen(subcommand, stdin=procs[-1].stdout, stdout=PIPE))
            procs.append(Popen(subcommands[-1], stdin=procs[-1].stdout, stdout=finalstdout))
        if not background and not returnoutput:
            procs[-1].wait()
    except Exception as error:
        raise RuntimeError("Problem while executing command %s (%s of %s)" %
                           (subcommands[len(procs)], len(procs) + 1, len(subcommands))) from error
    if not returnoutput:
        return True
    return procs[-1].communicate()[0]
class UPnPPortMapping:
    def add_port_mapping(self, router, protocol, public_port, private_ip, private_port,
                         mapping_description, lease_duration):
        """
        Function that adds a port mapping to the router.
        If a port mapping already exists, it is updated with a lease period of 24 hours.
        """
        from xml.etree import ElementTree
        url = '%s%s' % (router.base_url, router.control_url)
        log.add_debug("UPnP: Adding port mapping (%s %s/%s, %s) at url '%s'",
                      (private_ip, private_port, protocol, router.search_target, url))
        headers = {
            "Host": router.base_url,
            "Content-Type": "text/xml; charset=utf-8",
            "SOAPACTION": '"%s
        }
        body = (self.request_body % (router.service_type, public_port, protocol, private_port, private_ip,
                                     mapping_description, lease_duration)).encode('utf-8')
        log.add_debug("UPnP: Add port mapping request headers: %s", headers)
        log.add_debug("UPnP: Add port mapping request contents: %s", body)
        response = http_request(
            router.url_scheme, router.base_url, router.control_url,
            request_type="POST", body=body, headers=headers)
        xml = ElementTree.fromstring(response)
        if not xml.find(".//{http://schemas.xmlsoap.org/soap/envelope/}Body"):
            raise Exception("Invalid port mapping response: %s" % response.encode('utf-8'))
        log.add_debug("UPnP: Add port mapping response: %s", response.encode('utf-8'))
        error_code = xml.findtext(".//{urn:schemas-upnp-org:control-1-0}errorCode")
        error_description = xml.findtext(".//{urn:schemas-upnp-org:control-1-0}errorDescription")
        if error_code or error_description:
            raise Exception("Error code %(code)s: %(description)s" %
                            {"code": error_code, "description": error_description})
