                        for part in self.escape_base_amp(stoken):
                            yield part
                        after_equals = False
                        continue
                elif stoken == '=':
                    after_equals = True
                yield stoken
            else:
                if stoken.startswith('<'):
                    in_tag = True
                yield stoken

